import re
from typing import List, Dict, Any, Tuple

# Helpers are available as per description
# We assume they are imported into the environment: node_by_title, node_by_id, children, table_rows

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return every distinct entity (object) in the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # find the Objects list node
    obj_node = None
    for child_id in scope_node.get("children", []):
        node = node_by_id(doc, child_id)
        if node["kind"] == "list" and node["title"] == f"{scope}: Objects":
            obj_node = node
            break
    if not obj_node:
        return []

    res = []
    pattern = re.compile(r"Object\s+(\d+):\s+([^\(]+)")
    for line in obj_node["lines"]:
        m = pattern.match(line)
        if m:
            obj_id, desc = m.group(1).strip(), m.group(2).strip()
            res.append({"id": obj_id, "description": desc})
    return res


def recorded_end(doc: Dict[str, Any], scope: str) -> float or None:
    """The last frame number recorded in the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    # find Motion log table node
    motion_node = None
    for child_id in scope_node.get("children", []):
        node = node_by_id(doc, child_id)
        if node["kind"] == "table" and node["title"] == f"{scope}: Motion log":
            motion_node = node
            break
    if not motion_node:
        return None

    frames = []
    for _idx, row_dict in table_rows(motion_node):
        try:
            frames.append(float(row_dict["frame"]))
        except (KeyError, ValueError):
            pass
    return max(frames) if frames else None


def _parse_events_lines(doc: Dict[str, Any], scope: str) -> List[Tuple[int, Dict[str, Any]]]:
    """Return list of tuples (line_index, parsed info)."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    events_node = None
    for child_id in scope_node.get("children", []):
        node = node_by_id(doc, child_id)
        if node["kind"] == "list" and node["title"] == f"{scope}: Events":
            events_node = node
            break
    if not events_node:
        return []
    lines = events_node["lines"]
    parsed = []
    for idx, line in enumerate(lines):
        m_in_view = re.match(r"Frame\s+(\d+):\s+Object\s+(\d+).*in view", line)
        m_enter = re.match(r"Frame\s+(\d+):\s+Object\s+(\d+)\s+enters the scene", line)
        m_collide = re.match(r"Frame\s+(\d+):\s+Object\s+(\d+)\s+and\s+Object\s+(\d+)\s+collide", line)
        if m_in_view:
            parsed.append((idx, {"type":"in_view", "time":int(m_in_view.group(1)),
                                 "objects":[m_in_view.group(2)]}))
        elif m_enter:
            parsed.append((idx, {"type":"enter", "time":int(m_enter.group(1)),
                                 "objects":[m_enter.group(2)]}))
        elif m_collide:
            parsed.append((idx, {"type":"collide", "time":int(m_collide.group(1)),
                                 "objects":[m_collide.group(2), m_collide.group(3)]}))
    return parsed


def _first_motion_row(doc: Dict[str, Any], scope: str, obj_id: str, frame: int):
    """Return first motion log row for given object at given frame, if any."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None, None
    motion_node = None
    for child_id in scope_node.get("children", []):
        node = node_by_id(doc, child_id)
        if node["kind"] == "table" and node["title"] == f"{scope}: Motion log":
            motion_node = node
            break
    if not motion_node:
        return None, None
    for row_idx, row_dict in table_rows(motion_node):
        try:
            if row_dict["object"].startswith(obj_id) and int(row_dict["frame"]) == frame:
                return motion_node["node_id"], row_idx
        except (KeyError, ValueError):
            pass
    return None, None


