                if node_id is not None:
                    srcs = [[node_id, row_idx, ["x", "y", "vx", "vy", "speed"]]]
                    motion_node = node_by_id(doc, node_id)
                    for r_idx, r_dict in table_rows(motion_node):
                        if r_idx == row_idx:
                            fields = {c: float(r_dict[c]) for c in ["x", "y", "vx", "vy", "speed"]}
                            break
                else:
                    srcs = []
                    fields = {}

                results.append({
                    "id": f"enter_{obj_id}",
                    "time": float(frame),
                    "kind": "entry",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": srcs + [[events_node_id, idx]]
                })
    return results


