import re
from typing import Any, Dict, List, Tuple, Set

# The helper functions that the environment provides
# node_by_title(doc, title) -> node dict or None
# node_by_id(doc, node_id) -> node dict
# children(doc, node) -> list of child node dicts
# table_rows(node) -> iterator of (row_index, row_dict)

# --------------------------------------------------------------------------- #
# Internal helpers
# --------------------------------------------------------------------------- #

def _scope_node(doc: Dict[str, Any], scope: str) -> Dict[str, Any] | None:
    """Return the node dict for the scope title."""
    return node_by_title(doc, scope)


def _child_with_title(scope_node: Dict[str, Any], title: str) -> Dict[str, Any] | None:
    """Return the child node that has the exact title or is prefixed by title."""
    for child_id in scope_node.get("children", []):
        child = node_by_id(doc, child_id)
        if child and child.get("title").startswith(title):
            return child
    return None


def _parse_objects(scope_node: Dict[str, Any]) -> List[Dict[str, str]]:
    """Parse the Objects list in the scope."""
    obj_list = _child_with_title(scope_node, f"{scope_node['title']}: Objects")
    if not obj_list:
        return []

    pattern = re.compile(r"Object\s+(\d+):\s+(.+)")
    objs = []
    for line in obj_list.get("lines", []):
        m = pattern.match(line.strip())
        if m:
            obj_id, desc = m.group(1).strip(), m.group(2).strip()
            objs.append({"id": obj_id, "description": desc})
    return objs


def _parse_events(scope_node: Dict[str, Any]) -> List[Tuple[int, str, float, List[str]]]:
    """
    Parse the Events list.
    Return a list of tuples: (line_index, kind, frame, [obj_ids]).
    kind is one of: 'in_view', 'enter', 'exit', 'collision'
    """
    ev_node = _child_with_title(scope_node, f"{scope_node['title']}: Events")
    if not ev_node:
        return []

    in_view_pat = re.compile(r"Frame\s+(\d+):\s+Object\s+(\d+).*in view")
    enter_pat = re.compile(r"Frame\s+(\d+):\s+Object\s+(\d+)\s+enters the scene")
    exit_pat = re.compile(r"Frame\s+(\d+):\s+Object\s+(\d+)\s+exits the scene")
    collide_pat = re.compile(r"Frame\s+(\d+):\s+Object\s+(\d+)\s+collides?(?: with| with Object)\s+(\d+)")

    events = []
    for idx, line in enumerate(ev_node.get("lines", [])):
        m = in_view_pat.match(line)
        if m:
            events.append((idx, "in_view", int(m.group(1)), [m.group(2)]))
            continue
        m = enter_pat.match(line)
        if m:
            events.append((idx, "enter", int(m.group(1)), [m.group(2)]))
            continue
        m = exit_pat.match(line)
        if m:
            events.append((idx, "exit", int(m.group(1)), [m.group(2)]))
            continue
        m = collide_pat.match(line)
        if m:
            events.append((idx, "collision", int(m.group(1)), [m.group(2), m.group(3)]))
    return events


def _find_motion_row(
    motion_node: Dict[str, Any], frame: int, obj_id: str
) -> Tuple[int, Dict[str, str]] | Tuple[None, None]:
    """Return the first motion log row index and row dict for given frame and object id."""
    for row_idx, row in table_rows(motion_node):
        try:
            f = int(row.get("frame", -1))
            if f != frame:
                continue
        except Exception:
            continue
        obj_ref = row.get("object", "")
        if obj_ref.startswith(obj_id):
            return row_idx, row
    return None, None


def _motion_node(scope_node: Dict[str, Any]) -> Dict[str, Any] | None:
    """Return the Motion log table node for the scope."""
    return _child_with_title(scope_node, f"{scope_node['title']}: Motion log")


# --------------------------------------------------------------------------- #
# Public API
# --------------------------------------------------------------------------- #

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """All distinct objects that appear in the scope."""
    node = _scope_node(doc, scope)
    if not node:
        return []
    return _parse_objects(node)


def recorded_end(doc: Dict[str, Any], scope: str) -> float | None:
    """Last frame recorded in the scope."""
    node = _scope_node(doc, scope)
    if not node:
        return None
    motion = _motion_node(node)
    if not motion:
        return None
    max_frame = None
    for _, row in table_rows(motion):
        try:
            f = int(row.get("frame", -1))
            if f >= 0 and (max_frame is None or f > max_frame):
                max_frame = f
        except Exception:
            continue
    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """External entries into the process."""
    result: List[Dict[str, Any]] = []

    node = _scope_node(doc, scope)
    if not node:
        return []

    motion = _motion_node(node)
    ev_node = _child_with_title(node, f"{scope}: Events")
    if not ev_node or not motion:
        return []

    events = _parse_events(node)

    # Fields we care about from motion log
    field_names = ["x", "y", "vx", "vy", "speed"]

    for line_index, kind, frm, obj_ids in events:
        if kind not in {"in_view", "enter", "exit"}:
            continue
        for obj_id in obj_ids:
            row_idx, row = _find_motion_row(motion, frm, obj_id)
            if row is None:
                # If no motion entry at that exact frame, skip this input
                continue
            # Build fields dict from motion row
            fields: Dict[str, Any] = {}
            for fn in field_names:
                try:
                    fields[fn] = float(row[fn])
                except Exception:
                    pass
            # Build src list
            src = []
            # Include motion log row references
            src.append([motion["node_id"], row_idx, field_names])
            # Include the event line itself
            src.append([ev_node["node_id"], line_index])

            # Unique id: kind_obj_frame
            rec_id = f"{kind}_{obj_id}_{frm}"
            result.append(
                {
                    "id": rec_id,
                    "time": float(frm),
                    "kind": kind,
                    "entities": [obj_id],
                    "fields": fields,
                    "src": src,
                }
            )
    return result


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Internal events produced by the process."""
    result: List[Dict[str, Any]] = []

    node = _scope_node(doc, scope)
    if not node:
        return []

    ev_node = _child_with_title(node, f"{scope}: Events")
    if not ev_node:
        return []

    events = _parse_events(node)

    for line_index, kind, frm, obj_ids in events:
        if kind != "collision":
            continue
        src = [[ev_node["node_id"], line_index]]
        result.append(
            {
                "time": float(frm),
                "kind": "collision",
                "entities": obj_ids,
                "value": None,
                "src": src,
            }
        )
    return result


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """No explicit constants in this document."""
    return {}
